INSERT INTO "Route" ("RouteName", "CompanyId", "IsActive", "CreatedAt", "UpdatedAt")
SELECT 'Kuttiyadi', 1, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM "Route" WHERE LOWER("RouteName") IN ('kuttiyadi', 'kuttiady'));

INSERT INTO "Route" ("RouteName", "CompanyId", "IsActive", "CreatedAt", "UpdatedAt")
SELECT 'Nadapuram', 1, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
